import java.util.Scanner;

public class I {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int totalStudents = sc.nextInt();
        double inputNumber = Double.parseDouble(sc.next());
        long pValue = (long)(inputNumber * 10000);
        findMinimum(totalStudents, pValue);
    }

    public static void findMinimum(long total, long p) {
        long studiedCount = 0;
        long remainingStudents = total;

        while (true) {
            long zeroCount = remainingStudents * (remainingStudents - 1) * (remainingStudents - 2) / 6;
            long oneCount = studiedCount * remainingStudents * (remainingStudents - 1) / 2;
            long twoCount = studiedCount * (studiedCount - 1) * remainingStudents / 2;
            long threeCount = studiedCount * (studiedCount - 1) * (studiedCount - 2) / 6;

            long weightedSum = zeroCount * 0 + oneCount * 1 + twoCount * 2 + threeCount * 2;
            long totalComb = total * (total - 1) * (total - 2) / 6;

            if (weightedSum * 5000 >= p * totalComb) {
                System.out.println(studiedCount);
                return;
            }
            studiedCount++;
            remainingStudents--;
        }
    }
}
